@push('script')
<script>document.addEventListener('DOMContentLoaded',()=>{const search=document.getElementById('tx-search'),status=document.getElementById('tx-status'),rows=[...document.querySelectorAll('#tx-body tr[data-status]')],count=document.getElementById('tx-count');function filter(){const term=search.value.toLowerCase(),state=status.value;let visible=0;rows.forEach(row=>{const show=(!term||row.textContent.toLowerCase().includes(term))&&(!state||row.dataset.status===state);row.hidden=!show;if(show)visible++});count.textContent=`Menampilkan ${visible} settlement`}search.addEventListener('input',filter);status.addEventListener('change',filter)});</script>
@endpush
